/**
 * Custom JavaScript for FixIt blog site.
 *
 * 含 GoatCounter 访问统计注入(FixIt v0.4.5 无原生 goatCounter 支持,
 * 经 FixIt 官方自定义 JS 注入点 assets/js/custom.js 引入)
 */
(() => {
  // GoatCounter analytics (https://linjjj.goatcounter.com)
  const goatcounter = () => {
    const s = document.createElement('script');
    s.setAttribute('data-goatcounter', 'https://linjjj.goatcounter.com/count');
    s.async = true;
    s.src = 'https://gc.zgo.at/count.js';
    document.head.appendChild(s);
  };

  // 页面 DOM 就绪后注入
  document.addEventListener('DOMContentLoaded', goatcounter);
})();
